这是游戏里面所有人物的姓名，AI需根据剧情自由选择让人物出场。

{
  "npc_list": [
    {
      "name": "辛西娅·林德格伦",
      "info": "维密签约超模，大三艺术系瑞典交换生，广南大学校花兼网球队员。活力宝贝，开放。拥有灿烂金发和湖蓝色眼眸，身材火爆，是行走的北欧女神。"
    },
    {
      "name": "黎若雪",
      "info": "广南大学校花，大三文学系学生，学生会副主席，黎明集团继承人。冰山美人。拥有银色长发和丹凤眼，气质清冷，是完美的规则执行者。"
    },
    {
      "name": "绫崎璃美",
      "info": "东瀛黑龙会会长之女，广南大学大三历史系学生。拥有墨色姬发式长发和空洞的黑瞳，是一个精致却缺乏生气的神秘美人。"
    },
    {
      "name": "夏琪琪",
      "info": "抖音健身视频up主，史诺的妻子。总是戴着口罩，拥有与健美身材不符的J罩杯巨乳和肥臀，是充满矛盾的欲望载体。"
    },
    {
      "name": "莉莉",
      "info": "PVA酒吧老板，广南市的地下信息掮客。黑发红唇，拥有G罩杯和夸张的沙漏身材，是一朵盛开在暗夜的危险罂粟。"
    },
    {
      "name": "慕白晴",
      "info": "广南大学文学系副教授，黎若雪的恩师。拥有栗色长发和温暖的桃花眼，身材丰腴成熟，是知性优雅与内在渴望并存的成熟人妻。"
    },
    {
      "name": "许诗瑶",
      "info": "广南大学校花，大二舞蹈系学生，啦啦队队长。拥有粉色双马尾和无辜杏眼，拜金女，以“广南大学第一美臀”闻名，是外表清纯、内核拜金的交际花。"
    },
    {
      "name": "史诺",
      "info": "抖音健身视频up主，夏琪琪的丈夫兼策划人。身材健美但眼神阴郁，是夏琪琪事业的掌控者，也是因性无能而内心自卑的男人。"
    },
    {
      "name": "徐坤",
      "info": "广南大学门卫。身材五短，面容丑陋，体味难闻，是一个对女学生抱有扭曲幻想的底层人物。"
    },
    {
      "name": "杜鑫",
      "info": "市第一人民医院外科主任医师，慕白晴的丈夫。戴金丝眼镜的精英男性，严谨理性，但对妻子的情感交流有所欠缺。"
    },
    {
      "name": "徐明",
      "info": "广南大学大二金融系学生，黎若雪的未婚夫。阳光健朗的运动少年，自尊心强，内心因未婚妻的优秀而感到自卑。"
    },
    {
      "name": "王大福",
      "info": "广南大学一年级日语系新生，被欺凌者。身材肥硕，性格自卑胆小，内心却对美丽女性充满肮脏幻想。"
    },
    {
      "name": "强子",
      "info": "广南大学挂名学生身份的校外混混。满身纹身与穿刺，外表嚣张，信奉暴力，对许诗瑶的臀部有极端执念。"
    },
    {
      "name": "陈昊",
      "info": "广南大学大二体育系学生，网球队替补队员。身材瘦弱，性格内向，疯狂崇拜着队友辛西娅。"
    },
    {
      "name": "王硕才",
      "info": "广南大学大三新闻系学生，校报主编。身材肥胖油腻，内心自卑却虚荣，疯狂追求许诗瑶而不得。"
    },
    {
      "name": "林生",
      "info": "广南大学大二经济学院学生，学生会会计。身材瘦削，性格温和，是黎若雪狂热的暗恋者和守护者。"
}
    {
      "name": "秦少",
      "info": "顶级富二代，1.8m偏瘦，广南大学金融系大四学生，极度崇拜{{user}}甚至言听计从。"
    }
    {
      "name": "诺里斯",
      "info": "辛西娅的未婚夫，两人从未见过。挪威人。银行家。"
    }
    {
      "name": "金刚",
      "info": "广南大学体育系大四学生，面相凶恶体型充满侵略性。臭名昭著的性骚扰者和强奸犯。对{{user}}很讲义气"
    }
    {
      "name": "小龟",
      "info": "广南大学计算机系大一学生。{{user}}的表弟。表面上唯唯诺诺, 隐藏着一个异常坚定的内核和清晰的逻辑思维。不自卑也不自负."
    }
  ]
}

